{
  "contract": "AmenoToken",
  "closure": {
    "site_function": "swapAndSendMarketingFee",
    "site_call": ".call",
    "functions": [
      "swapAndSendMarketingFee",
      "transfer",
      "transferFrom"
    ],
    "justification": "The function swapAndSendMarketingFee involves a low-level call that may re-enter the contract, potentially calling transfer or transferFrom."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "transfer",
      "transferFrom"
    ],
    "nesting_bound": {
      "swapAndSendMarketingFee": 1
    }
  },
  "phases": {
    "function": "swapAndSendMarketingFee",
    "pre": {
      "name": "pre",
      "from_marker": "entry",
      "to_marker": "before call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before call",
      "to_marker": "after call"
    },
    "post": {
      "name": "post",
      "from_marker": "after call",
      "to_marker": "exit"
    },
    "linearization_point": "after call"
  },
  "ghost_state": [
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "The additional pending marketing fee in flight during reentrancy.",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "pendingMarketingFee + pendingBurnFee + inFlight <= _balances[address(this)]",
    "stable_formula": "pendingMarketingFee + pendingBurnFee <= _balances[address(this)]",
    "kind": "additive"
  },
  "composition": {
    "target_property": "pendingMarketingFee + pendingBurnFee <= _balances[address(this)]",
    "rule": "The exposure invariant ensures that during the reentrancy window, the combined pending fees and any in-flight transfers do not exceed the balance of the contract. This guarantees that the target property is maintained across the reentrant call."
  }
}
